mysql --defaults-file=.claude/database/my.cnf.prod --batch --raw -e "
DESC ads.ads_app_metrics_hourly_d;
"

mysql --defaults-file=.claude/database/my.cnf.prod --batch --raw -e "
SHOW TABLES FROM information_schema LIKE '%load%';
SELECT TABLE_NAME, UPDATE_TIME, CREATE_TIME, TABLE_ROWS
FROM information_schema.tables_config
WHERE TABLE_SCHEMA='ads' AND TABLE_NAME='ads_app_metrics_hourly_d';
"

mysql --defaults-file=.claude/database/my.cnf.prod --batch --raw -e "
DESC information_schema.stream_loads;
SELECT '---loads---';
DESC information_schema.loads;
"

mysql --defaults-file=.claude/database/my.cnf.prod --batch --raw -e "
SHOW PARTITIONS FROM ads.ads_app_metrics_hourly_d WHERE PartitionName='p20260912';
"

mysql --defaults-file=.claude/database/my.cnf.prod --batch --raw -e "
SHOW TABLES FROM dws LIKE '%retention%';
SHOW TABLES FROM ads LIKE '%source%';
SHOW TABLES FROM ads LIKE '%channel%';
SHOW TABLES FROM dws LIKE '%page_visit%';
"

mysql --defaults-file=.claude/database/my.cnf.prod --batch --raw -e "
DESC ads.ads_source_analysis_metric_d;
DESC dws.dws_source_analysis_retention_d;
"

mysql --defaults-file=.claude/database/my.cnf.prod --batch --raw -e "
SHOW TABLES FROM ads LIKE '%source%';
SHOW TABLES FROM dws LIKE '%source%';
SHOW TABLES FROM dwd LIKE '%landing%';
SHOW TABLES FROM dwd LIKE '%refer%';
"

mysql --defaults-file=.claude/database/my.cnf.prod --batch --raw -e "
DESC dws.dws_source_analysis_active_d;
SELECT * FROM dws.dws_source_analysis_active_d WHERE app_id='JHG-024' AND dt='2026-09-11' LIMIT 30;
"

mysql --defaults-file=.claude/database/my.cnf.prod --batch --raw -e "
DESC dwd.dwd_landing_page_view_d;
"

mysql --defaults-file=.claude/database/my.cnf.prod --batch --raw -e "
DESC ads.ads_product_day_stat_d;
"

mysql --defaults-file=.claude/database/my.cnf.prod --batch --raw -e "
SHOW COLUMNS FROM dwd.dwd_app_page_view_d LIKE '%refer%';
SHOW COLUMNS FROM dwd.dwd_app_page_view_d LIKE '%source%';
SHOW COLUMNS FROM dwd.dwd_landing_page_click_d LIKE '%refer%';
SELECT COUNT(*) AS landing_view, COUNT(DISTINCT uid) AS uv
FROM dwd.dwd_landing_page_view_d
WHERE app_id='JHG-024' AND dt='2026-09-11';
SELECT COUNT(*) AS landing_click, COUNT(DISTINCT uid) AS uv
FROM dwd.dwd_landing_page_click_d
WHERE app_id='JHG-024' AND dt='2026-09-11';
"

mysql --defaults-file=.claude/database/my.cnf.prod --batch --table -e "
SHOW CREATE TABLE ads.ads_source_analysis_metric_d;
"

mysql --defaults-file=.claude/database/my.cnf.prod --batch --raw -e "
SELECT 'funnel' AS k, SUM(new_users) AS new_users, SUM(page_view_user_cnt) AS pv, SUM(video_exposure_user_cnt) AS exp, SUM(first_play_user_cnt) AS play, MAX(update_time) AS upd
FROM dws.dws_user_reg_video_funnel_daily_d
WHERE app_code='JHG-024' AND dt='2026-09-11';
SELECT 'app_user' AS k, BITMAP_UNION_COUNT(new_users) AS new_u, BITMAP_UNION_COUNT(active_users) AS act, MAX(update_time) AS upd
FROM dws.dws_app_user_d_h
WHERE app_code='JHG-024' AND dt='2026-09-11';
SELECT 'retention' AS k, SUM(new_users) AS new_users, MAX(update_time) AS upd
FROM dws.dws_app_retention_d
WHERE app_code='JHG-024' AND dt='2026-09-11';
SELECT source_group, new_user_cnt FROM ads.ads_source_analysis_metric_d WHERE app_id='JHG-024' AND dt='2026-09-11';
SELECT DISTINCT source_group FROM ads.ads_source_analysis_metric_d WHERE dt>='2026-09-01' LIMIT 20;
"

mysql --defaults-file=.claude/database/my.cnf.prod --batch --raw -N -e "
SELECT TABLE_COMMENT FROM information_schema.tables WHERE TABLE_SCHEMA='dws' AND TABLE_NAME='dws_source_analysis_active_d';
SELECT COLUMN_NAME, COLUMN_COMMENT FROM information_schema.columns WHERE TABLE_SCHEMA='dws' AND TABLE_NAME='dws_source_analysis_active_d';
"
